import{_ as a,a0 as r,w as O,s as o,I as t,x as i,a1 as n,A as p,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const g=JSON.parse(`{"title":"是时候合并 LibreOffice 和 OpenOffice 了 | LCTT x X-CMD","titleTemplate":false,"description":"是时候合并 LibreOffice 和 OpenOffice 了 | LCTT (201609) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"是时候合并 LibreOffice 和 OpenOffice 了 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"是时候合并 LibreOffice 和 OpenOffice 了 | LCTT (201609) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201609/20160914 It's time to make LibreOffice and OpenOffice one again","title":"是时候合并 LibreOffice 和 OpenOffice 了","tag":"201609","desc":""},"relativePath":"201609/20160914 It's time to make LibreOffice and OpenOffice one again.md","filePath":"[post].md"}`),c={name:"201609/20160914 It's time to make LibreOffice and OpenOffice one again.md"};function s(b,e,d,m,L,u){const f=r("Link");return O(),o("div",null,[e[18]||(e[18]=t("h1",{id:"是时候合并-libreoffice-和-openoffice-了",tabindex:"-1"},[i("是时候合并 LibreOffice 和 OpenOffice 了 "),t("a",{class:"header-anchor",href:"#是时候合并-libreoffice-和-openoffice-了","aria-label":"Permalink to “是时候合并 LibreOffice 和 OpenOffice 了”"},"​")],-1)),e[19]||(e[19]=t("p",null,[t("img",{src:"http://tr2.cbsistatic.com/hub/i/2016/09/14/2e91089b-7ebd-4579-bf8f-74c34d1a94ce/e7e9c8dd481d8e068f2934c644788928/openofficedeathhero.jpg",alt:""})],-1)),t("p",null,[e[2]||(e[2]=i("先说下 OpenOffice。可能你已经无数次地看到说 Apache OpenOffice 即将结束。上一个稳定版本是 4.1.2 （发布于 2015 年 10 月），而最近的一个严重安全漏洞用了一个月才打上补丁。编码人员的缺乏使得开发如爬行前进一般。然后，可能是最糟糕的消息了：这个项目建议用户切换到 ",-1)),n(f,{href:"https://products.office.com/"},{default:p(()=>[...e[0]||(e[0]=[i("MS Office",-1)])]),_:1}),e[3]||(e[3]=i("（或 ",-1)),n(f,{href:"https://www.libreoffice.org/download/"},{default:p(()=>[...e[1]||(e[1]=[i("LibreOffice",-1)])]),_:1}),e[4]||(e[4]=i(")。",-1))]),e[20]||(e[20]=l('<p>丧钟为谁而鸣？丧钟为你而鸣，OpenOffice。</p><p>我想说些可能会惹恼一些人的话。你准备好了吗？</p><p>OpenOffice 的终止对开源和用户来说都将是件好事。</p><p>让我解释一下。</p><h3 id="一个分支统治所有" tabindex="-1">一个分支统治所有 <a class="header-anchor" href="#一个分支统治所有" aria-label="Permalink to “一个分支统治所有”">​</a></h3><p>当 LibreOffice 从 OpenOffice 分支出来后，我们看到了另一个情况：分支不只在原始基础上进行改进，而且大幅超越了它。LibreOffice 一举成功。所有之前预装 OpenOffice 的 Linux 发行版都迁移到了这个新项目。LibreOffice 从起跑线突然冲出，并迅速迈出了一大步。更新以极快的速度发布，改善内容丰富而重要。</p><p>不久后，OpenOffice 就被开源社区丢在了脑后。当 2011 年 Oracle 决定终止这个项目并把代码捐赠给 Apache 项目时，这种情况自然更加恶化了。从此 OpenOffice 艰难前进，然后把我们就看到了现在这种局面：一个生机勃勃的 LibreOffice 和一个艰难的、缓慢的 OpenOffice。</p><p>但我认为在这个相当昏暗的隧道末尾有一丝曙光。</p><h3 id="合并他们" tabindex="-1">合并他们 <a class="header-anchor" href="#合并他们" aria-label="Permalink to “合并他们”">​</a></h3><p>这听起来可能很疯狂，但我认为是时候把 LibreOffice 和 OpenOffice 合二为一了。是的，我知道很可能有政治考虑和自尊意识，但我认为合并成一个会更好。合并的好处很多。我首先能想到的是：</p><ul><li>把 MS Office 过滤器整合起来：OpenOffice 在更好地导入某些 MS Office 文件上功能很强（而众所周知 LibreOffice 正在改进，但时好时坏）</li><li>LibreOffice 有更多开发者：尽管 OpenOffice 的开发者数量不多，但也无疑会增加到合并后的项目。</li><li>结束混乱：很多用户以为 OpenOffice 和 LibreOffice 是同一个东西。有些甚至不知道 LibreOffice 存在。这将终结那些混乱。</li><li>合并他们的用户量：OpenOffice 和 LibreOffice 各自拥有大量用户。联合后，他们将是个巨大的力量。</li></ul><h3 id="宝贵机遇" tabindex="-1">宝贵机遇 <a class="header-anchor" href="#宝贵机遇" aria-label="Permalink to “宝贵机遇”">​</a></h3><p>OpenOffice 的终止实际上会成为整个开源办公套件行业的一个宝贵机遇。为什么？我想表明有些东西我认为已经需要很久了。如果 OpenOffice 和 LibreOffice 集中他们的力量，比较他们的代码并合并，他们之后就可以做一些更必要的改进工作，不仅是整体的内部工作，也包括界面。</p><p>我们得面对现实，LibreOffice 和（相关的） OpenOffice 的用户界面都是过时的。当我安装 LibreOffice 5.2.1.2 时，工具栏绝对是个灾难（见下图）。</p><p><img src="http://tr2.cbsistatic.com/hub/i/2016/09/14/cc5250df-48cd-40e3-a083-34250511ffab/c5ac8eb1e2cb12224690a6a3525999f0/openofficea.jpg" alt=""></p><p><em>LibreOffice 默认工具栏显示</em></p><p>尽管我支持和关心（并且日常使用）LibreOffice，但事实已经再清楚不过了，界面需要完全重写。我们正在使用的是 90 年代末/ 2000 年初的复古界面，它必须得改变了。当新用户第一次打开 LibreOffice 时，他们会被淹没在大量按钮、图标和工具栏中。Ubuntu Unity 的平视显示（Head up Display，简称 HUD）帮助解决了这个问题，但那并不适用于其它桌面和发行版。当然，有经验的用户知道在哪里找什么（甚至定制工具栏以满足特殊的需要），但对新用户或普通用户，那种界面是个噩梦。现在是做出改变的一个好时机。引入 OpenOffice 最后残留的开发者并让他们加入到改善界面的战斗中。借助于整合 OpenOffice 额外的导入过滤器和现代化的界面，LibreOffice 终能在家庭和办公桌面上都引起一些轰动。</p><h3 id="这会真的发生吗" tabindex="-1">这会真的发生吗？ <a class="header-anchor" href="#这会真的发生吗" aria-label="Permalink to “这会真的发生吗？”">​</a></h3><p>这需要发生。但是会发生吗？我不知道。但即使掌权者决定用户界面并不需要重组（这会是个失误），合并 OpenOffice 仍是前进的一大步。合并两者将带来开发的更专注，更好的推广，公众更少的困惑。</p><p>我知道这可能看起来有悖于开源的核心精神，但合并 LibreOffice 和 OpenOffice 将能联合两者的力量，而且可能会摆脱弱点。</p><p>在我看来，这是双赢的。</p><hr>',22)),t("p",null,[e[6]||(e[6]=i("via: ",-1)),n(f,{href:"http://www.techrepublic.com/article/its-time-to-make-libreoffice-and-openoffice-one-again/"},{default:p(()=>[...e[5]||(e[5]=[i("http://www.techrepublic.com/article/its-time-to-make-libreoffice-and-openoffice-one-again/",-1)])]),_:1})]),t("p",null,[e[10]||(e[10]=i("作者：",-1)),n(f,{href:"http://www.techrepublic.com/search/?a=jack%2Bwallen"},{default:p(()=>[...e[7]||(e[7]=[i("Jack Wallen",-1)])]),_:1}),e[11]||(e[11]=i(" 译者：",-1)),n(f,{href:"https://github.com/bianjp"},{default:p(()=>[...e[8]||(e[8]=[i("bianjp",-1)])]),_:1}),e[12]||(e[12]=i(" 校对：",-1)),n(f,{href:"https://github.com/wxy"},{default:p(()=>[...e[9]||(e[9]=[i("wxy",-1)])]),_:1})]),t("p",null,[e[15]||(e[15]=i("本文由 ",-1)),n(f,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[13]||(e[13]=[i("LCTT",-1)])]),_:1}),e[16]||(e[16]=i(" 原创编译，",-1)),n(f,{href:"https://linux.cn/"},{default:p(()=>[...e[14]||(e[14]=[i("Linux中国",-1)])]),_:1}),e[17]||(e[17]=i(" 荣誉推出",-1))])])}const x=a(c,[["render",s]]);export{g as __pageData,x as default};
